import {chapterFrame,storyOpening,aiPage} from './external-journey-frame.js?v=20260921-streamlined2';
import {vendorConfig} from './vendor-config.js?v=20260921-portals1';
import {cases} from './workshop.js?v=20260921-readiness1';

const e=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let view='experience';
let stageIndex=0;
const checked=new Set();

const stages=[
  ['Discover','Nadia finds the Harborline Integration Exchange through a branded partner invitation.','The application explains the relationship, requested data and support boundary before sign-up.'],
  ['Register','She creates an External ID account in the customer tenant.','The user flow collects only the profile attributes needed to begin partner verification.'],
  ['Verify','Harborline connects Nadia to Crestline’s approved integration agreement.','Trusted business context comes from the partner registry, not from a company name typed during registration.'],
  ['Consent','Nadia sees the exact API permissions and data use before approval.','Consent is specific, understandable and recorded for the external application relationship.'],
  ['Develop','The developer workspace issues a sandbox client and least-privilege API scope.','The API validates issuer, audience, subject, expiry and current partner authorization on every request.'],
  ['Step up','Publishing a production credential requires stronger assurance.','Sensitive actions can demand recent authentication without adding friction to ordinary sandbox work.'],
  ['Change','A new API scope follows a reviewable request and approval.','The application keeps identity, partner agreement and technical authorization as separate decisions.'],
  ['Expire','The engagement ends and partner access closes without creating an employee offboarding task.','The application revokes credentials and relationships, then retains evidence of the completed boundary.']
];

const proof=[
  ['Correct external tenant','External tenant','Show the application, associated sign-up/sign-in user flow and Nadia’s customer record.'],
  ['Trusted partner mapping','Partner registry','Show Nadia’s stable subject linked to Crestline, the sponsor and effective dates.'],
  ['Least-privilege scope','Integration Exchange','Run GET /v1/reservations/preview and show 200 ALLOW with reservations.read.'],
  ['Production boundary','Resource API','Run the prepared production publish action and show 403 DENY with the missing scope.'],
  ['One correlation trail','Sign-in + API logs','Match subject, application, timestamp, resource, scope and result across both systems.'],
  ['Restored baseline','Tenant + application','Remove the prepared change, revoke the test session and prove the denial still holds.']
];

function journey(){return `<div class="vendor-journey partner-journey" aria-label="Nadia’s External ID lifecycle"><span>EXTERNAL ID JOURNEY</span>${stages.map((stage,index)=>`<button data-partner="stage" data-index="${index}" class="${index===stageIndex?'active':''}" aria-pressed="${index===stageIndex}"><b>0${index+1}</b><small>${e(stage[0])}</small></button>`).join('')}</div>`;}

function workspace(){return `<section class="partner-workspace"><div class="partner-story"><span class="vendor-kicker">THE COMPLETE JOURNEY</span><h2>A developer joins the ecosystem.<br><em>She never becomes an employee.</em></h2><p>Nadia works for Crestline, an approved integration partner. She registers through Harborline’s branded External ID flow, is matched to a verified partner agreement, consents to narrowly defined data use and receives only the sandbox API scope her project needs. Publishing a production credential triggers stronger assurance and an approval. When the engagement ends, Harborline removes the partner relationship and credentials while preserving the identity and application evidence needed for audit.</p><div class="partner-principle"><b>IDENTITY</b><span>Who is Nadia?</span><b>RELATIONSHIP</b><span>Does she represent Crestline?</span><b>AUTHORIZATION</b><span>Which API action is allowed now?</span></div></div><aside class="partner-console"><header><span>HARBORLINE</span><small>INTEGRATION EXCHANGE</small></header><div class="partner-console-user"><i>NH</i><div><strong>Nadia Haddad</strong><span>Crestline · Integration developer</span></div><em>EXTERNAL</em></div><div class="partner-console-grid"><div><small>ENVIRONMENT</small><strong>Sandbox</strong><span>Ready</span></div><div><small>API SCOPE</small><strong>reservations.read</strong><span>Approved</span></div><div><small>PRODUCTION</small><strong>Credential publish</strong><span>Step-up required</span></div><div><small>AGREEMENT</small><strong>31 Dec 2026</strong><span>Time-bound</span></div></div><div class="partner-api"><span>GET /v1/reservations/preview</span><b>200 · ALLOW</b></div><div class="partner-api denied"><span>POST /v1/properties/harbor-view</span><b>403 · DENY</b></div><div class="partner-live-actions"><a href="${e(vendorConfig.integrationPortalUrl)}" target="_blank" rel="noopener noreferrer">Open live Integration Exchange ↗</a><small>LIVE PARTNER APPLICATION CONNECTED · WORKSPACE PREVIEW BELOW</small></div></aside></section>`;}

function architecture(){return `<section class="partner-decision-architecture"><header><div><span class="vendor-kicker">NADIA’S REQUEST · WHO DECIDES WHAT?</span><h2>Four decisions turn a sign-in into a safe API call.</h2><p>Use this view while the tenant and Integration Exchange are open. Each card names the owner, the decision and the exact proof to show.</p></div><span>LIVE DEMO MAP</span></header><div class="partner-decision-flow"><article><b>01</b><span>IDENTITY</span><h3>Microsoft Entra External ID</h3><strong>Is this Nadia?</strong><p>User flow authenticates her and issues a stable subject.</p><em>SHOW · customer record + sign-in event</em></article><i>subject</i><article><b>02</b><span>BUSINESS TRUST</span><h3>Partner registry</h3><strong>Does she represent Crestline?</strong><p>Sponsor, agreement and dates establish the relationship.</p><em>SHOW · subject → company mapping</em></article><i>partner</i><article><b>03</b><span>TECHNICAL SCOPE</span><h3>Token validation</h3><strong>Is this token valid here?</strong><p>Issuer, audience, expiry and scope form the API contract.</p><em>SHOW · aud + reservations.read</em></article><i>request</i><article class="decision"><b>04</b><span>ENFORCEMENT</span><h3>Resource API</h3><strong>May she do this now?</strong><p>The API combines token and current partner authorization.</p><em>SHOW · 200 ALLOW + 403 DENY</em></article></div><div class="partner-request-trace"><span>REQUEST UNDER TEST</span><div><b>SUBJECT</b><strong>Nadia’s stable External ID subject</strong></div><div><b>PARTNER</b><strong>Crestline · agreement active</strong></div><div><b>SCOPE</b><strong>reservations.read</strong></div><div><b>RESOURCE</b><strong>Sandbox reservations</strong></div><div class="allow"><b>DECISION</b><strong>200 · ALLOW</strong></div></div><div class="partner-ownership"><div><span>SYSTEM</span><span>OWNS</span><span>VERIFY LIVE</span></div><div><strong>External tenant</strong><p>Authentication and stable subject</p><em>Application, user flow, customer record, sign-in</em></div><div><strong>Partner registry</strong><p>Company relationship and effective dates</p><em>Crestline mapping, sponsor, agreement status</em></div><div><strong>Integration Exchange</strong><p>Consent and developer experience</p><em>Sandbox workspace and requested scope</em></div><div><strong>Resource API</strong><p>Action-level authorization</p><em>Allowed read and denied production publish</em></div></div><div class="partner-architecture-takeaway"><span>THE POINT TO TEACH</span><strong>A successful sign-in proves a person. It does not prove a company relationship or authorize an API action.</strong><a class="outline" href="#nadia/live">Run this architecture live →</a></div></section>`;}

function liveDemo(){return `<section class="external-live-stage"><header><div><span class="vendor-kicker">TWO LIVE SIDES · PARTNER API BOUNDARY</span><h2>Configure the relationship.<br><em>Prove the API decision.</em></h2><p>Keep the External ID administrator beside Nadia’s partner workspace so the room can see how tenant configuration becomes an allowed or denied action.</p></div><button class="primary" data-partner="desktop">Launch the two-sided stage →</button></header><div class="external-live-panes"><article><div class="live-pane-top"><span>ADMINISTRATOR</span><b>01</b></div><div class="live-pane-icon">ID</div><h3>External tenant</h3><p>Inspect the application, user flow, Nadia’s external account and the authentication event.</p><ul><li>Confirm tenant and application</li><li>Inspect user flow and collected claims</li><li>Correlate sign-in and assurance</li></ul><strong>Left side · protected admin desktop</strong></article><div class="external-live-link"><span>CONFIGURE</span><b>→</b><span>ENFORCE</span></div><article class="customer"><div class="live-pane-top"><span>PARTNER DEVELOPER</span><b>02</b></div><div class="live-pane-icon">NH</div><h3>Integration Exchange</h3><p>Sign in as Nadia, run an allowed sandbox request, attempt a denied production action and explain the result.</p><ul><li>Complete External ID sign-in</li><li>Prove an allowed API scope</li><li>Prove a denied action</li></ul><strong>Right side · connected Integration Exchange</strong></article></div><div class="external-live-run"><div><span>RECOMMENDED DEMO SEQUENCE</span><strong>Admin baseline → Nadia signs in → sandbox allows → production denies → evidence confirms</strong></div><div><a class="outline" href="${e(vendorConfig.integrationPortalUrl)}" target="_blank" rel="noopener noreferrer">Open live Integration Exchange ↗</a><button class="outline" data-partner="desktop">Open admin + partner sessions ↗</button></div></div></section>`;}

function evidence(){return `<section class="partner-proof-board"><header><div><span class="vendor-kicker">NADIA’S PROOF BOARD</span><h2>One identity. Two API decisions. Evidence the room can follow.</h2><p>Start with the claim, show the record, and check it only after the audience sees the evidence.</p></div><div class="partner-proof-outcomes"><span><b>200</b> Sandbox read allowed</span><span class="deny"><b>403</b> Production publish denied</span></div></header><div class="partner-correlation"><span>CORRELATE ON</span><b>External ID subject</b><i>+</i><b>Application ID</b><i>+</i><b>UTC timestamp</b><i>+</i><b>Correlation ID</b></div><div class="partner-proof-grid">${proof.map(([title,source,description],index)=>`<label class="partner-proof-card"><input type="checkbox" data-partner-proof="${index}" ${checked.has(index)?'checked':''}><span class="proof-number">${String(index+1).padStart(2,'0')}</span><span class="proof-source">${e(source)}</span><strong>${e(title)}</strong><p>${e(description)}</p><em>${checked.has(index)?'SHOWN TO THE ROOM':'SHOW THIS LIVE'}</em></label>`).join('')}</div><div class="partner-proof-summary"><strong>${checked.size} / ${proof.length}</strong><span>evidence points shown</span><progress max="${proof.length}" value="${checked.size}"></progress></div><div class="partner-evidence-actions"><a class="outline" href="https://entra.microsoft.com/?tid=${e(vendorConfig.externalTenantId)}" target="_blank" rel="noopener noreferrer">Open external tenant ↗</a><a class="outline" href="${e(vendorConfig.integrationPortalUrl)}" target="_blank" rel="noopener noreferrer">Open Integration Exchange ↗</a><a class="primary" href="#nadia/live">Open two-sided live demo →</a></div><section class="franchise-replay"><div><span class="vendor-kicker">RESET &amp; REPLAY</span><h3>End where you started.</h3><p>Remove the test production scope, restore the sandbox assignment, revoke the prepared session and run the denied action again. The restored 403 is the final proof.</p></div><div><span class="vendor-kicker">CLIENT QUESTION</span><blockquote>Could your team connect one customer sign-in to the exact business and API decision that followed?</blockquote></div></section></section>`;}

export function partnerPage(mode='experience'){
  view=['experience','architecture','live','ai','evidence'].includes(mode)?mode:'experience';
  const meta={experience:['THE STORY','Invite the partner. <em>Protect the API.</em>','Follow one external developer from branded registration to scoped API access and clean expiration.'],architecture:['ARCHITECTURE','Separate identity, trust and <em>technical authorization.</em>','Show where External ID ends, where partner context begins and where the API makes the decision.'],live:['LIVE DEMO','Show both sides. <em>Prove allow and deny.</em>','Place the external-tenant administrator beside Nadia’s developer experience.'],ai:['HOW AI HELPS','Explain the API decision. <em>Change only with approval.</em>','Use AI to correlate sign-in, partner and API evidence before a narrow, reversible change.'],evidence:['EVIDENCE','Prove the person. <em>Prove the scope.</em>','Connect Nadia’s sign-in to partner trust, consent, token claims and API enforcement.']}[view];
  const story=storyOpening({headline:'An integration developer arrives.<br><em>The employee directory stays untouched.</em>',summary:'Nadia Haddad represents Crestline, an approved integration partner. External ID gives her a branded way into Harborline’s developer ecosystem while the application keeps company trust, API scope and expiration explicit.',initials:'NH',name:'Nadia Haddad',role:'Integration developer · Crestline',truth:'Her sign-in establishes a person. The partner registry and API decide which systems and actions that relationship allows.',portrait:'./assets/personas/nadia-haddad.webp',outcomes:[['Register','Branded partner user flow'],['Verify','Trusted company relationship'],['Authorize','Least-privilege API scope'],['Expire','Revoke access and prove it']]});
  const ai=aiPage({kicker:'AI COPILOT · NADIA’S PARTNER API ACCESS',title:'Trace the denial. <em>Protect the production boundary.</em>',summary:'The assistant correlates Nadia’s authentication, partner agreement, consent and API decision, proposes one scoped correction and waits for human approval before any change.',buttonAttr:'data-partner="desktop"',flow:[['Observe','Read the selected sign-in, token and API response.'],['Correlate','Match Nadia’s subject to Crestline and current scopes.'],['Propose','Draft the smallest time-bound scope correction.'],['Approve + run','A presenter authorizes the prepared change.'],['Verify + undo','Re-run allow and deny, then restore baseline.']],inputs:['External ID sign-in and authentication details','Partner agreement, sponsor and effective dates','Token claims, API request and authorization result'],outputs:['A cited explanation of the exact denial','A preview of the scope and expiration change','Before, after and restored API outcomes'],guardrail:'The assistant cannot turn registration data into partner trust or bypass API enforcement. The live Integration Exchange is connected; configuration changes remain approval-controlled and must be verified against tenant and API evidence.'});
  const content=view==='experience'?story+workspace():view==='architecture'?architecture():view==='live'?liveDemo():view==='ai'?ai:evidence();
  return chapterFrame({classes:'partner-shell',accent:'#58d6ff',glow:'#163d68',topline:'MICROSOFT ENTRA EXTERNAL ID · PARTNER DEVELOPER JOURNEY',name:'NADIA HADDAD',role:'INTEGRATION DEVELOPER',section:meta[0],title:meta[1],summary:meta[2],route:'nadia',view,nav:[['experience','01','The story'],['live','02','Live demo'],['ai','03','How AI helps']],context:['EXTERNAL TENANT','Business customer','Partner verification','Scoped API authorization'],status:'LIVE · Harborline Integration Exchange connected',content,footer:'Nadia · external tenant partner developer journey'});
}

export function installPartnerEvents(render,onDesktop){document.addEventListener('click',event=>{const button=event.target.closest('[data-partner]');if(!button)return;const action=button.dataset.partner;if(action==='desktop'){onDesktop();return;}if(action==='stage'){stageIndex=Number(button.dataset.index);if(view==='experience'&&stageIndex>1)location.hash='#nadia/architecture';render();}});document.addEventListener('change',event=>{if(!event.target.matches('[data-partner-proof]'))return;const index=Number(event.target.dataset.partnerProof);event.target.checked?checked.add(index):checked.delete(index);render();document.querySelector(`[data-partner-proof="${index}"]`)?.focus();});}

export function nadiaGuide(){const step=(action,why,look)=>({action,why,look});return {name:'Nadia Haddad',time:'Partner developer journey',title:'Invite the partner. Protect the API.',job:'Integration developer',perspective:'Partner experience',liveUrl:vendorConfig.integrationPortalUrl,liveLabel:'Harborline Integration Exchange',liveKind:'partner application',story:'Nadia registers in the external tenant, is linked to Crestline and receives only the API scope her project requires.',why:'Show that External ID authenticates the partner while the application preserves business trust, least privilege and clean expiration.',account:'Prepared Nadia External ID test account',domain:'External tenant · verify in the administrator profile',cases:cases.filter(c=>[10,12,14,16,29,32,33,34].includes(c.id)),highlights:['Show the associated user flow','Verify Crestline partner context','Prove allowed and denied API calls'],admin:[step('Open the External ID tenant and inspect the Integration Exchange application and associated sign-up/sign-in user flow.','The partner experience must use the customer tenant and intended application registration.','Verify tenant, application ID, redirect URI, flow association, identity providers and collected attributes.'),step('Inspect the trusted partner mapping for Nadia, Crestline, approved scopes and agreement dates.','Self-asserted sign-up attributes cannot grant API authority.','Show the stable External ID subject, partner record, sponsor, effective dates and scope source.'),step('Correlate one successful sign-in with an allowed sandbox request and a denied production request.','Authentication and API authorization are separate controls.','Match subject, audience, scope, timestamp, resource and API decision.')],user:[step('Open the prepared Integration Exchange in Nadia’s separate browser profile.','Keep the partner experience separate from the administrator session.','Use privately held credentials and the configured authentication method.'),step('Review consent, open the sandbox workspace and run the prepared read request.','The audience should see useful access that is narrow by design.','Show the real consent and API result only when the application is connected.'),step('Attempt the prepared production action and request additional scope.','A denied request makes the enforcement boundary visible.','Show the API denial and any step-up or approval only if implemented and rehearsed.')],userTitle:'Experience Nadia’s partner developer workspace',evidence:'Correlate External ID sign-in, trusted partner relationship, consent, token claims and the application/API decision.',caution:'The live Integration Exchange is connected. Verify Nadia’s sign-in, partner mapping, allowed sandbox call, denied production call and reset path before each client session.',question:'Where does your application decide that this authenticated partner may perform this API action right now?'};}
